examples.source:
#include <stdio.h>
int main(void) {
    int markers = 9;
    printf("markers=%d\n", markers);
    return 0;
}

#include <stdio.h>
int main(void) {
    int soundings = 3;
    int feet = soundings * 6;
    printf("fathoms=%d feet=%d\n", soundings, feet);
    return 0;
}

#include <stdio.h>
void show_middle(void);
int main(void) {
    printf("begin\n");
    show_middle();
    printf("end\n");
    return 0;
}
void show_middle(void) {
    printf("inside helper\n");
}

#include <stdio.h>
int main(void) {
    int labels = 4
    printf("labels=%d\n", labels);
    return 0;
}

#include <stdio.h>
int main(void) {
    int edge = 3;
    int face = edge * edge;
    int volume = face * face;
    printf("volume=%d\n", volume);
    return 0;
}

